// Normalize the incoming GitHub URL and convert blob -> raw
const input = $input.first().json;
const body = input.body || input;
let url = (body.repoUrl || body.githubUrl || body.url || '').toString().trim();

if (!url) {
  throw new Error('No GitHub URL provided. Send JSON { "repoUrl": "<github file url>" }.');
}

// Basic shape validation
if (!/^https?:\/\//i.test(url)) {
  throw new Error('Invalid URL. Provide a full http(s) GitHub file URL.');
}

let rawUrl = url;
// github.com/<owner>/<repo>/blob/<branch>/<path>  ->  raw.githubusercontent.com/<owner>/<repo>/<branch>/<path>
const m = url.match(/^https?:\/\/github\.com\/([^\/]+)\/([^\/]+)\/blob\/(.+)$/i);
if (m) {
  rawUrl = `https://raw.githubusercontent.com/${m[1]}/${m[2]}/${m[3]}`;
}

// strip any query string / fragment from raw url
rawUrl = rawUrl.split('#')[0].split('?')[0];

const fileName = rawUrl.split('/').pop() || 'source';

return [{ json: { sourceUrl: url, rawUrl, fileName } }];
